from collections import deque


class Cell:
    """Base class shared by input and compute cells.

    A cell can have *dependents* (compute cells that read its value) and
    *callbacks* (notified when the cell's value settles at a new value).
    """

    def __init__(self):
        self._callbacks = []
        self._dependents = []

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        # Identity-based removal so that removing an unregistered (or already
        # removed) callback is a safe no-op that never disturbs others.
        for i, registered in enumerate(self._callbacks):
            if registered is callback:
                del self._callbacks[i]
                break

    def _add_dependent(self, cell):
        self._dependents.append(cell)

    def _fire_callbacks(self, value):
        for callback in list(self._callbacks):
            callback(value)

    def _collect_affected(self):
        """Return the set of compute cells transitively downstream of this cell."""
        affected = set()
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if cell in affected:
                continue
            affected.add(cell)
            stack.extend(cell._dependents)
        return affected

    def _topo_sort(self, affected):
        """Order affected cells so each is evaluated after its (affected) inputs."""
        in_degree = {
            cell: sum(1 for inp in cell.inputs if inp in affected)
            for cell in affected
        }
        queue = deque(cell for cell in affected if in_degree[cell] == 0)
        order = []
        while queue:
            cell = queue.popleft()
            order.append(cell)
            for dep in cell._dependents:
                if dep in affected:
                    in_degree[dep] -= 1
                    if in_degree[dep] == 0:
                        queue.append(dep)
        return order


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        if new_value == self._value:
            return
        self._value = new_value
        self._propagate()

    def _propagate(self):
        # Recompute every affected cell to a new stable state, then notify.
        # Callbacks fire only for cells whose value actually changed, and each
        # fires exactly once with the final value.
        affected = self._collect_affected()
        order = self._topo_sort(affected)
        for cell in order:
            cell._recompute()
        for cell in order:
            if cell._changed:
                cell._fire_callbacks(cell._value)
            cell._changed = False


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self.inputs = inputs
        self.compute_function = compute_function
        self._value = compute_function([inp.value for inp in inputs])
        self._changed = False
        for inp in inputs:
            inp._add_dependent(self)

    @property
    def value(self):
        return self._value

    def _recompute(self):
        new_value = self.compute_function([inp.value for inp in self.inputs])
        self._changed = new_value != self._value
        self._value = new_value
